class IPayloadBackend
{
public:

    virtual PayloadID store(...) = 0;

    virtual bool load(...) = 0;

  2010|    virtual bool erase(...) = 0;

    virtual bool contains(...) = 0;

    virtual ~IPayloadBackend() = default;
